var legacyMap = new Map(legacy_portrait_assets_default.map((legacy, index) => [legacy, portrait_assets_default[index]]));
function normalizePortraitImage(image) {
  if (!image) return image;
  return legacyMap.get(image) ?? image;
}
var ASSISTANT_PORTRAIT = portraits[0];
var PORTRAITS = portraits.slice(1);
var portraitsFor = (generalAssistant) => generalAssistant === true ? portraits : PORTRAITS;
var isPortrait = (image) => portraits.some((portrait) => portrait.image === image) || legacyMap.has(image);

